"use client";
import { useEffect, useState, useRef } from "react";
import { Input } from "@/components/ui/input";
import { Button } from "@/components/ui/button";
import { Avatar, AvatarImage, AvatarFallback } from "@/components/ui/avatar";
import { getProfile, updateProfile } from "@/app/api/patient/profile";
import { Select, SelectItem } from "@/components/ui/MultiSelect ";

const GENDERS = ["male", "female", "other"];
const BLOOD_GROUPS = ["A+", "A-", "B+", "B-", "AB+", "AB-", "O+", "O-"];
const MEDICAL_HISTORY_OPTIONS = [
  "Diabetes", "Hypertension", "Cancer", "Heart", "Asthma", "Allergy", "Other"
];

export default function ProfilePage() {
  const [user, setUser] = useState(null);
  const [form, setForm] = useState({
    fullName: "",
    email: "",
    phone: "",
    age: "",
    gender: "",
    bloodGroup: "",
    country: "",
    medicalHistory: [],
  });
  const [loading, setLoading] = useState(false);
  const [image, setImage] = useState(null);
  const fileInputRef = useRef();

  useEffect(() => {
    async function fetchProfile() {
      const userId = localStorage.getItem("userId");
      setLoading(true);
      const res = await getProfile(userId);
      setUser(res);
      setForm({
        fullName: res.fullName || "",
        email: res.email || "",
        phone: res.phone || "",
        age: res.age || "",
        gender: res.gender || "",
        bloodGroup: res.bloodGroup || "",
        country: res.country || "",
        medicalHistory: res.medicalHistory || [],
      });
      setLoading(false);
    }
    fetchProfile();
  }, []);

  const handleChange = (e) => {
    setForm({ ...form, [e.target.name]: e.target.value });
  };

  const handleSelectChange = (name, value) => {
    setForm({ ...form, [name]: value });
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    setLoading(true);
    const res = await updateProfile(form);
    if (res.ok) {
      const data = await res;
      setUser(data);
      alert("Profile updated!");
    }
    setLoading(false);
  };

  const handleImageChange = async (e) => {
    const file = e.target.files[0];
    if (!file) return;
    setLoading(true);
    const token = localStorage.getItem("token");
    const formData = new FormData();
    formData.append("avatar", file);
    const res = await fetch("/api/patient/me/avatar", {
      method: "POST",
      headers: { Authorization: `Bearer ${token}` },
      body: formData,
    });
    if (res.ok) {
      const data = await res.json();
      setUser(data);
      alert("Profile image updated!");
    }
    setLoading(false);
  };

  if (loading && !user) return <div className="p-8">Loading...</div>;
  if (!user) return <div className="p-8">No user found.</div>;

  return (
    <div className="max-w-xl mx-auto  bg-white p-8 rounded shadow-md mt-8">
      <h2 className="text-2xl font-bold mb-4">My Profile</h2>
      <form onSubmit={handleSubmit} className="space-y-4">
        <div className="flex items-center gap-4 mb-4">
          <Avatar className="w-20 h-20">
            <AvatarImage src={user.avatarUrl} alt={user.fullName} />
            <AvatarFallback>{user.fullName?.charAt(0)}</AvatarFallback>
          </Avatar>
          <Button type="button" variant="outline" onClick={() => fileInputRef.current.click()}>
            Change Photo
          </Button>
          <input
            type="file"
            accept="image/*"
            ref={fileInputRef}
            className="hidden"
            onChange={handleImageChange}
          />
        </div>
        <div>
          <label className="block font-medium mb-1">Full Name</label>
          <Input name="fullName" value={form.fullName} onChange={handleChange} required />
        </div>
        <div>
          <label className="block font-medium mb-1">Email</label>
          <Input name="email" value={form.email} onChange={handleChange} required disabled />
        </div>
        <div>
          <label className="block font-medium mb-1">Phone</label>
          <Input name="phone" value={form.phone} onChange={handleChange} />
        </div>
        <div>
          <label className="block font-medium mb-1">Age</label>
          <Input name="age" type="number" value={form.age} onChange={handleChange} />
        </div>
        <div>
          <label className="block font-medium mb-1">Gender</label>
          <Select name="gender" value={form.gender} onValueChange={v => handleSelectChange("gender", v)}>
            {GENDERS.map(g => (
              <SelectItem key={g} value={g}>{g.charAt(0).toUpperCase() + g.slice(1)}</SelectItem>
            ))}
          </Select>
        </div>
        <div>
          <label className="block font-medium mb-1">Blood Group</label>
          <Select name="bloodGroup" value={form.bloodGroup} onValueChange={v => handleSelectChange("bloodGroup", v)}>
            {BLOOD_GROUPS.map(bg => (
              <SelectItem key={bg} value={bg}>{bg}</SelectItem>
            ))}
          </Select>
        </div>
        <div>
          <label className="block font-medium mb-1">Address</label>
          <Input name="country" value={form.country} onChange={handleChange} />
        </div>
        <div>
          <label className="block font-medium mb-1">Medical History</label>
          <MultiSelect
            options={MEDICAL_HISTORY_OPTIONS}
            value={form.medicalHistory}
            onChange={v => handleSelectChange("medicalHistory", v)}
            name="medicalHistory"
            placeholder="Select medical history"
          />
        </div>
        <Button type="submit" disabled={loading} className="w-full">
          {loading ? "Saving..." : "Save Changes"}
        </Button>
      </form>
    </div>
  );
} 